mapper.select:
SELECT ws.*
FROM s_weekly_slot ws
JOIN s_court c ON c.id = ws.court_id
WHERE c.venue_id = #{venueId}
AND ws.status = #{status}
ORDER BY ws.day_of_week, ws.start_time, c.name

SELECT COUNT(*)
FROM s_weekly_slot
WHERE court_id = #{courtId}
  AND day_of_week = #{dayOfWeek}
  AND status = 'ACTIVE'
  AND start_time < #{endTime}
  AND end_time > #{startTime}
AND id != #{excludedId}
FOR UPDATE
